const S={"job":["Workday Education · Job Profiles","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/job-profiles.html"],"staff":["Workday Education · Staffing Models","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/staffing-models.html"],"org":["Workday · Organization Management","https://www.workday.com/content/dam/web/en-us/documents/datasheets/organization-management-in-workday-datasheet-en-us.pdf"],"roles":["Workday Education · Role-Based Security","https://doc.workday.com/workday-education/en-us/course-manuals/security-for-administrators/role-based-security.html"],"bp":["Workday Education · Business Process Framework","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/business-process-framework.html"],"bpa":["Workday Administrator Guide · Business Processes","https://doc.workday.com/admin-guide/en-us/manage-workday/business-processes/business-process-framework-concepts/dan1370797198449.html"],"notify":["Workday Administrator Guide · Custom Notifications","https://doc.workday.com/admin-guide/en-us/manage-workday/business-processes/business-process-notifications/dan1370797382653.html"],"report":["Workday Education · Report Writer and Custom Reports","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/report-writer-and-custom-reports.html"],"custom":["Workday Administrator Guide · Create Custom Reports","https://doc.workday.com/admin-guide/en-us/reporting-and-analytics/custom-reports-and-analytics/set-up-reports/dan1370797785951.html"],"security":["Workday Education · Configurable Security Framework","https://doc.workday.com/workday-education/en-us/course-manuals/security-for-administrators/configurable-security-framework.html"],"groups":["Workday Administrator Guide · Create Security Groups","https://doc.workday.com/admin-guide/en-us/use-case-library/use-case--create-security-groups.html?toc=8"],"policy":["Workday Education · Security Policy Configuration","https://doc.workday.com/workday-education/en-us/course-manuals/security-for-administrators/security-policy-configuration-and-activation.html"],"b1":["Course book · HCM Core for Administrators (25R2)","https://bookshelf.vitalsource.com/reader/books/HCMCOREADMIN-25R2"],"b2":["Course book · HCM Core Supplemental for Administrators (25R2)","https://bookshelf.vitalsource.com/reader/books/HCMCORESUPPADMIN-25R2"],"cj":["Workday Education · Change Job Configurations","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/change-job-configurations.html"],"term":["Workday Education · Termination and Business Process Templates","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/termination-and-business-process-templates.html"],"comp":["Workday Education · Compensation Framework","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/compensation-framework.html"],"nav":["Workday Education · Workday Tenants and Tools","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/workday-tenants-and-tools.html"],"secadv":["Workday Education · Advanced Security Group Types","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/advanced-security-group-types.html"],"bpadv":["Workday Education · Advanced Business Process Configurations","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/advanced-business-process-configurations.html"],"hire":["Workday Education · Prepare for Hire","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/prepare-for-hire.html"],"orgs":["Workday Education · Organizations and Hierarchies","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-for-administrators/organizations-and-hierarchies.html"],"valid":["Workday Education · Validations in Workday","https://doc.workday.com/workday-education/en-us/course-manuals/hcm-core-supplemental-for-administrators/validations-in-workday.html"]};
const D=[['staffing','Staffing Setup',25],['organizations','Organizations',20],['business','Business Processes',25],['reporting','Reporting',5],['security','Security',25]];
const L=[
["job-families","staffing","Job Families & Groups","Organize job profiles into optional reporting and filtering hierarchies.","A job profile may belong to one or more job families; a family can belong to a family group. Families can support prompt filters, reports, Recruiting categories, condition rules, and eligibility rules.","Job family|Groups related profiles;Job family group|Groups families into a broader catalog layer","A compensation rule uses the Engineering family. Add a new Software Engineer profile to that family or the expected default may not apply.","Create Job Family;Job Family report;Edit Job Profile;Job Catalog","A family classifies work; it is not a supervisory organization or staffing model.","What does a job family organize?|Job profiles.","Why must a new profile join a family used by an eligibility rule?|To satisfy the rule criteria|To create a supervisory org|To activate security|To choose a staffing model",0,"Family membership can determine whether rule criteria are satisfied.","job,b1","B1 pp. 157–159, 189"],
["job-profiles","staffing","Create & Edit Job Profiles","Define reusable characteristics used by jobs and positions.","Job profiles describe general work characteristics. Optional fields include title, management level, classifications, pay rate type, compensation grade, qualifications, country restriction, and description.","Job profile|Reusable work definition;Job or position|Staffable instance in an organization","Use one Executive Assistant profile across multiple positions instead of duplicating the definition for each department.","Create Job Profile;Edit Job Profile;Job Catalog;Edit Tenant Setup - HCM","A profile is not a worker and is not the same as a position. Effective-dated edits can affect staffing, eligibility, and reporting.","What job-profile fields are normally required?|Name, job code, and effective date.","Which record provides reusable characteristics to jobs and positions?|Job profile|Security group|Supervisory organization|Business process",0,"A job profile is the reusable catalog definition.","job,b1","B1 pp. 157–165, 190, 288"],
["job-management","staffing","Job Management Options","Use organization-level restrictions for flexible, high-volume staffing.","Job Management emphasizes speed and flexibility. Reporting covers current headcount only, so control relies on hire, contract, and transfer workflows. Restriction criteria are the same for both models: job family, job profile, location, worker type, worker sub type, time type, or No Job Restrictions (you must choose at least one). Edit Tenant Setup - HCM can allow users to override restrictions during staffing events; the restriction values still default in.","Best fit|Flexible or high-volume staffing;Restriction level|Supervisory organization;Changing the model|Edit Staffing Model, only before positions or restrictions exist","A support center hires many agents under shared job, location, worker-type, subtype, and time-type restrictions.","Edit Staffing Model;Maintain Staffing Models;Set Hiring Restrictions","Edit Staffing Model works in either direction only until positions exist (Position Management) or hiring restrictions are set (Job Management). After that the task is no longer available, so choose the model before staffing begins.","Where do Job Management restrictions apply?|Across the supervisory organization.","A team needs flexible hiring without persistent vacancies. Which model?|Job Management|Position Management|Role-based security|Job family group",0,"Job Management uses organization-level restrictions and favors flexibility.","staff,hire,b1","B1 pp. 116–122, 188–189, 194"],
["position-management","staffing","Position Management Options","Control persistent individual positions, restrictions, vacancies, and history.","A position exists independently from its incumbent. You can report on open and filled positions and on position history, assign company, cost center, and region to unfilled positions, and move positions between organizations.","Best fit|Individual seat and vacancy control;Restriction level|Individual position;Changing the model|Edit Staffing Model, only before positions or restrictions exist","A hospital must control and report every approved nursing seat, including vacancies and position history.","Create Position;Edit Position Restrictions;Maintain Staffing Models","Do not choose Job Management when the scenario requires persistent vacancy or position-level history. Once positions are created, Edit Staffing Model is no longer available, so choose the model before staffing begins.","What remains after an incumbent leaves?|The position.","Leadership must report every approved vacancy. Which model?|Position Management|Job Management|Custom organization|User-based security",0,"Position Management preserves the position independently of the worker.","staff,hire,b1","B1 pp. 116–122, 188–190, 199"],
["staffing-processes","staffing","Staffing Business Processes","Prepare the organization, then run Hire and its subprocesses.","Prepare first. A Position Management organization needs an open position (Create Position business process); a Job Management organization needs hiring restrictions (Hiring Restrictions business process). Hire works the same under both models. Other values default: management level, job classification, and work shift from the job profile, and weekly hours from the location. When a position and its job profile both hold a value, the position wins. A typical Hire definition adds the Propose Compensation Hire and Change Organization Assignments subprocesses, a Review Employee Hire action, a Create Workday Account service step, and To Dos. Change Job and Termination have their own lessons.","Create Position|Prepares a Position Management organization;Hiring Restrictions|Prepares a Job Management organization;Hire|Brings a worker into a position or job;Common Hire steps|Propose Compensation Hire, Change Organization Assignments, Review Employee Hire, Create Workday Account","A manager cannot hire into a position-managed organization until a position is available.","Create Position;Set Hiring Restrictions;Hire Employee;Propose Compensation Hire;Change Organization Assignments for Worker","If Hire is missing from an organization's Related Actions, the organization is not prepared: create a position (Position Management) or set hiring restrictions (Job Management).","What comes before Hire in Position Management?|An available position.","No position is available in a position-managed org. What comes first?|Create or make a position available|Reassign the worker's job profile|Add the position to a security group|Switch the report to a prompt",0,"An available position is a prerequisite.","staff,bp,hire,b1,b2","B1 pp. 179–190, 271–273, 288–290 · B2 pp. 31–32"],
["change-job","staffing","Change Job","Configure promotions, transfers, demotions, lateral moves, and location changes.","Change Job supports promotions, demotions, transfers, lateral moves, and changes to position data and location. Both run the Change Job business process. Maintain Change Job Templates sets the fields, sections, subprocesses, reasons, and help text for templates on Change Job, Change Location, Request Transfer, and Change Contingent Worker Details. Moving a manager can move all of their eligible teams or none, each through its own Assign Superior subprocess. Assign Roles - Change Assignments for Worker reviews roles, and it is not rescinded if Change Job is rescinded.","Start Job Change|Manager task with simple template questions;Transfer, Promote or Change Job|Administrator task with the full guided editor;Request Transfer|For a group without direct access to the worker;Routing modifier|Sends a step to the current or proposed group member","A manager wants to bring a worker from another organization onto their team. They have no access to that worker, so they use the Request Transfer micro-task; the receiving manager and HR Partner then review it.","Start Job Change;Transfer, Promote or Change Job;Maintain Change Job Templates;Maintain Event Categories and Reasons;Configure Consolidated Template","Change Job uses a template, so a group needs both the BP security policy (to start or act) and the domain policies (to see each section). Rescinding Change Job does not undo new role assignments.","Which two tasks start the Change Job process?|Start Job Change and Transfer, Promote or Change Job.","A manager must transfer in a worker they cannot access yet. Which initiating action fits?|Request Transfer|Change Location|Start Job Change|Change Contractor Details",0,"Request Transfer lets a group without direct access to the worker start the transfer (B2 p. 126).","cj,b2","B2 pp. 116–130"],
["termination","staffing","Termination","End employment, clean up the worker's tasks and roles, and secure the template.","Termination ends the working relationship. Start it with Terminate Employee (worker Related Actions > Job Change), through Submit Resignation (the Termination process must include the Review Worker Initiated Termination step), or through Severance. Last Day of Work and Pay Through Date default to the termination date. You can record rehire eligibility, regrettable or not, a questionnaire such as an exit interview, notice periods, and attachments. Maintain Termination Categories holds customer-defined reasons with Involuntary, Retirement, Inactive, and Manager Reason flags. Typical steps: Manage Business Processes for Worker (reassign or cancel the worker's tasks), Assign Roles, and a Terminate User Account service step.","Terminate Employee|Initiated by a manager or HR;Submit Resignation|Worker-initiated, needs the Review Worker Initiated Termination step;Manage Business Processes for Worker|Reassign or cancel the leaver’s tasks;No Show|Hire never started, not counted in headcount","An HR Partner is leaving. Add Manage Business Processes for Worker to reassign their open tasks, Assign Roles to move their roles, and Terminate User Account to end system access. Mark the position available for overlap so the replacement can shadow them.","Terminate Employee;Maintain Termination Categories;Manage Business Processes for Worker;Edit Workday Account;View Business Process Template;Template-Driven Business Process Security","Adding a group to the Termination BP policy lets it start the task, but it cannot see the Reason or Details sections until it is added to their domain policies (for example Staffing Actions: Termination Details).","When does a terminated worker show as terminated?|Just after midnight at the end of the termination date, in their time zone.","Which step reassigns or cancels a terminating worker's open My Tasks items?|Manage Business Processes for Worker|Assign Roles|Complete Questionnaire|Service Dates Change",0,"Manage Business Processes for Worker lists the worker's tasks, processes about them, and delegations (B2 p. 80).","term,b2","B2 pp. 74–101, 272–273"],
["compensation","staffing","Compensation Basics","See how packages, grades, plans, and eligibility rules default pay during staffing.","A compensation package groups compensation grades and plans. A grade gives a pay range (minimum, midpoint, and 3, 4, or 5 segments) as guidance: a salary outside the range gives a warning, not an error. Plans hold pay components: salary, hourly, period salary, and unit salary for base pay, and allowance plans (amount, percent, or unit based). Compensation elements link plans to payroll earnings.","Package|Groups grades and plans;Grade vs grade profile|Pay range vs localized range;Eligibility rule|Who can receive a component;Element|Links a plan to payroll earnings","A worker is eligible for a car allowance plan that is not in their package. The plan does not default during Hire, but the compensation partner can add it by hand.","Create Compensation Eligibility Rule;Create Compensation Grade;Create Salary Plan;Create Allowance Plan;Create Compensation Package;Test Compensation Eligibility Rule","Eligible for two packages or two grades means nothing defaults. Eligible for a plan outside the package means it is selectable but does not default.","What groups compensation grades and plans?|A compensation package.","What determines whether a worker is eligible for a compensation component?|A compensation eligibility rule|The compensation grade profile|The compensation package name|The worker's pay group",0,"Eligibility rules control which components a worker can receive and which default (B1 p. 126).","comp,b1","B1 pp. 55, 124–155, 161"],
["organization-types","organizations","Define & Describe Organizations","Use organization types as distinct lenses for management, legal, costing, pay, and reporting needs.","The supervisory organization groups workers into the management hierarchy and holds positions and job restrictions; every worker belongs to exactly one. Workers usually also belong to a company (legal entity, tax ID), cost center (revenue and expense), region (area of responsibility), pay group (payroll), and location, and can be in several matrix organizations (dotted-line manager). Create custom organization types only when delivered types do not fit. Fields when creating an organization: Availability Date (when it appears in prompts), Name, Code, Subtype (tenanted; can enforce a subtype hierarchy), Visibility, and roles; supervisory organizations add External URL, Primary Location (required), Staffing Model, and Identifiers. Maintain Organization Types groups types into Costing, Hierarchy, HR, Pay, and Custom.","Supervisory org|Who manages whom, and where staffing happens;Other organization types|Legal, costing, pay, location, or customer-defined views;Inherited by subordinates|Visibility, Primary Location, Staffing Model, Roles;Visibility options|Everyone, Role Assignees, Role Assignees and Members, Role Assignees of Current and Superiors","Use a supervisory organization for management and a cost center for cost reporting rather than forcing one structure to do both jobs.","Create Supervisory Organization;Create Company;Create Cost Center;Create Location;Maintain Organization Types;Maintain Organization Subtypes","A worker can have several organization assignments but only one primary supervisory organization.","Which organization forms the HCM management hierarchy?|Supervisory organization.","Which organization answers “who manages this worker?”|Supervisory organization|Cost center organization|Company organization|Region organization",0,"The supervisory organization is the management hierarchy.","org,roles,orgs,b1","B1 pp. 54, 62–69, 78–79, 89–91, 101–103"],
["organization-hierarchies","organizations","Organization Hierarchies","Roll up organizations of one type for reporting, and use reorganization events to date changes.","An organization hierarchy rolls up organizations of its own type for reporting: a cost center hierarchy holds only cost centers, a location hierarchy only locations. One organization can sit in several hierarchies, and hierarchies can include other hierarchies. Assign roles such as HR Partner (by location) on a location hierarchy, not on individual locations; workers join a location hierarchy by being hired or contracted with an included location. Creating or changing organizations and hierarchies uses a reorganization event, which groups activities under one common effective date.","Hierarchy|Rollup of one organization type for reporting and role inheritance;Reorganization event|Groups changes under one effective date;Organization|Where transactions are recorded","Roll three cost centers into an IT Services cost center hierarchy. Costs are charged to each cost center and roll up automatically; the management chain does not change.","Create Cost Center Hierarchy;Create Location Hierarchy;Reorganization > Assign Included Organizations;Reorganization > Assign Locations;Create Reorganization;Reorganizations report","A hierarchy never stores transactions. Location-based roles go on a location hierarchy, not on a single location.","Why create an organization hierarchy?|Reporting rollups and role inheritance.","What can a location hierarchy include?|Locations and other location hierarchies|Locations, cost centers, and companies together|Any organization type the owner selects|Only supervisory organizations",0,"A hierarchy holds only its own organization type, and hierarchies can include other hierarchies (B1 p. 82).","org,roles,orgs,b1","B1 pp. 71, 82–87, 103–104"],
["organization-assignments","organizations","Organization Assignments","Configure values that default and values that users are allowed to select.","Default assignments propose an initial organization value during staffing. A default should normally also be allowed. Allowed values also drive what can be chosen in the Default prompt, and workers hired or transferred into the organization automatically join its default organizations. A subordinate organization inherits the Default and Allowed organizations of its superior unless it has its own values; the Inherited from Superior check box on the Organization Assignments tab shows this, and entering a value overrides the inherited one.","Default|Proposed starting value;Allowed|Valid selection set","Default Cost Center 4100 but permit two approved alternatives in the allowed set.","Assign Organizations;Edit Supervisory Organization;Hire;Change Job","A default value is not necessarily the only permitted value. Check defaults, allowed values, and inheritance together.","Default versus allowed?|Default proposes; allowed constrains choices.","A value should prepopulate but two alternatives remain valid. Configure?|A default and allowed set|A required validation condition|A single fixed notification value|A user-based security group",0,"Default and allowed assignments solve different parts of the requirement.","org,orgs,b1","B1 pp. 97–100, 104"],
["assignable-roles","organizations","Assignable Roles","Connect responsibility to a position or job for a role-enabled organization.","Assignable roles can drive role-based security membership, business-process routing, and reporting responsibility.","Assignable role|Responsibility for a role-enabled instance;Role-based group|Membership derived from role assignment","Leave the HR Partner role attached to an unfilled position so a replacement can assume responsibility when hired.","View Assignable Roles;Maintain Assignable Roles;Assign Roles;Roles for Organization and Subordinates","A role is not permission by itself. Group membership plus policy permission produces access.","What can an unassigned role cause?|An unassigned workflow task.","Why attach a role to a position?|A replacement can assume it|It deletes a policy|It changes staffing model|It prevents inheritance",0,"The role can remain through incumbent changes.","roles,b1","B1 pp. 66–67, 225–233, 290"],
["bp-framework","business","BP Terminology & Framework","Understand type, definition, event, steps, routing, conditions, and security.","A business process type is the event category; a definition is its configured workflow; an event is one transaction running through that definition.","Type|Event category;Definition|Configured workflow;Event|One running transaction","Two hires use the same Hire definition but create separate events routed for their own subjects and organizations.","View Business Process Definition;Business Process Configuration Options;Business Process Definitions for Business Object;Find Events;View Event","Do not confuse the reusable definition with one running event.","Type, definition, event?|Category, configured workflow, running transaction.","What is one running transaction called?|Business process event|Business process type|Business process definition|Business process step",0,"An event is one instance of a definition.","bp,bpa,b1,b2","B1 pp. 55–56, 179–186, 259–269 · B2 pp. 15–16, 23–24"],
["bp-definitions","business","Update BP Definitions","Choose between default, organization-specific, and rule-based definitions, and set the completion step.","Workday delivers business process types; you configure definitions. Use rule-based definitions when the same condition rule would sit on three or more steps, or when the path depends on who initiates or where workers are. The completion step commits the data and sets Successfully Completed. A process has only one, and all approvals and reviews must come before it or be it.","Default|Recommended and easiest to maintain;Organization-specific|Own steps for an organization whose flow differs greatly;Rule-based|One condition rule, checked once at initiation, picks the definition;Completion step|Commits data, and approvals and reviews come first","Hires in three countries follow different approval paths, and the same location rule sits on four steps of the default. Replace those step conditions with three rule-based definitions, one per location rule.","Edit Definition;Inactivate Business Process Definition;Set as Completion;Business Process Definitions for Business Object","A rule-based definition uses exactly one condition rule (it can nest conditions) and only fields that have a value at initiation. Approvals and reviews never come after the completion step.","What does the completion step control?|Data commit and successful-completion status.","Many conditions make the default hard to audit for one org with very different steps. What may simplify it?|An organization-specific definition|A different job family|A separate domain override|An added report prompt",0,"An organization-specific definition gives that org its own steps instead of many conditions on the default.","bp,bpa,b1,b2","B1 pp. 262–263, 269, 274, 283–285 · B2 pp. 16–20, 54–55, 64, 129"],
["bp-advanced","business","Routing, Delays & Effective Dates","Control who acts on a step, when it runs, and which definition version applies.","Maintain Advanced Routing adds routing restrictions: Exclude Initiator, Exclude Prior Approvers, and Exclude Event Subject. If everyone assigned is excluded, the step is skipped unless you name an alternate security group, relative to the transaction or to the excluded user. Use routing restrictions when exclusion depends on how a user is involved in this event; use condition rules to exclude groups regardless of the event. Maintain Step Delay pauses the process before a step, based on the prior step's completion, the initiation date, or a field such as Effective Date; Recalculate Delay on Correct keeps it accurate. Rule-based calendars are set per business process type. An event uses the definition that is in effect when it is initiated, never a future-dated version, and subprocesses use the version in effect when the parent started.","Routing restriction|Excludes someone by their role in this event;Condition rule|Excludes regardless of the event;Step delay|Pauses before a step runs;Definition version|The one in effect at initiation","An HR Partner both starts and reviews hires. Add Exclude Initiator on the review step and route it to the HR Partner's manager as the alternate, relative to the excluded user.","Maintain Advanced Routing;Maintain Step Delay;Reschedule Delayed Business Process Transactions;Rule Based Calendar Configuration;Maintain Business Process Definition Selection","An event initiated June 14 uses the version effective then, even if its effective date is June 29 and a newer version starts June 16.","Which setting stops an initiator from approving their own event?|Maintain Advanced Routing with Exclude Initiator.","An HR Partner initiated a hire and should not also review it. What do you configure?|A routing restriction: Exclude Initiator|An entry condition on initiation|A step delay on the review|A second organization-specific definition",0,"Routing restrictions exclude users based on their interaction with the event (B2 pp. 35–36).","bp,bpadv,b2","B1 pp. 268, 270 · B2 pp. 30, 35–40, 64"],
["bp-steps","business","Business Process Step Types","Match initiation, action, approval, service, and to-do behavior to the requirement.","Initiation starts the event and is always first. To Do steps send an Inbox reminder for work inside or outside Workday; Workday delivers none, so you create them with Maintain To Dos.","Approval|Formal decision, no editing;Action|A review (with editing) or a subprocess;Service|Workday-delivered automation;To Do|Reminder for work Workday may not check","Use Approval for a formal approve-or-deny decision; do not substitute a To Do checkbox.","Edit Business Process Definition;Add Step;View Diagram","Completing a To Do proves the click, not necessarily the external activity.","Which step represents automation?|Service.","Which step requires a formal approve-or-deny decision?|Approval|To Do|Service|Initiation",0,"Approval captures the decision and controls routing.","bp,bpa,bpadv,b1,b2","B1 pp. 262–267 · B2 pp. 25–30, 49–50"],
["conditions","business","Condition Rules","Distinguish entry, validation, while-running, and exit conditions.","Entry decides whether a step runs; it works on every step type except Initiation. Validation checks data on Initiation and Action (review) steps and stops the process if a condition applies. A validation is either Warning (the user can continue) or Critical (the user must fix the data), and you can write a custom validation message. Create Condition Rule only saves a rule; Maintain Step Conditions attaches it to a step.","Entry|Should the step start?;Validation|May the process continue? (Warning or Critical);While Running|Does the next chain member act?;Exit|May the running step complete?","Run executive approval only above a compensation threshold by attaching an entry condition.","Create Condition Rule;Maintain Step Conditions;Configure Validation Message;Test Rule;Configure Optional Fields","The four types are not interchangeable and are not available on every step type.","Name the four condition types.|Entry, validation, while running, and exit.","Approval runs only above a threshold. Which condition?|Entry|Exit|Validation|While Running",0,"Entry decides whether the step begins or is skipped.","bp,valid,b1,b2","B1 pp. 270, 274–277 · B2 pp. 53–56, 61, 67–73"],
["notifications","business","Business Process Notifications","Communicate progress without granting access or replacing required steps.","Workday sends system notifications, for example when a task arrives in My Tasks. Delivery depends on configuration and preferences: immediate email, a daily digest email, and push notifications. Edit Tenant Setup - Notifications holds tenant-wide email and delivery settings. Select Do Not Include Notification Details Link for recipients who have no Workday account.","Notification|Inform someone;BP step|Require or automate work;Trigger|Status, or step entry or exit;System vs custom|Custom ones do not turn system ones off","Email a hiring manager when Hire completes, using only fields that recipient is authorized to view.","Add Notification;Maintain System Notifications;Maintain Email Templates;Mass Update Email Address Option on Notifications;Edit Tenant Setup - Notifications","A notification is not an Approval or Action and does not confer access.","Does a notification grant event access?|No.","Why might a dynamic field show “[not available]”?|The recipient lacks field access|The staffing model has changed|The job family is empty|The hierarchy is inactive",0,"Notification content respects field security.","notify,bp,bpadv,b2","B2 pp. 41–45, 64"],
["standard-reports","reporting","Identify Standard Reports","Use Workday-delivered reports and understand purpose, type, security, and scheduling.","The Workday Standard Reports report lists every delivered report with its category, description, type (XpressO or Report Writer), whether it is schedulable, and its securing domain. Common standard reports by purpose: plan and configure business processes with Business Process Configuration Options; see which definition an organization uses with Business Process Definitions for Business Object; track organization activity with Reorganizations and Organization Exception Audit; view job profiles with Job Catalog and Job Family.","Run delivered|Use when it meets the need;Copy or custom|Use when requirements differ;Plan business processes|Business Process Configuration Options;Track organization activity|Reorganizations, Organization Exception Audit;View job profiles|Job Catalog, Job Family","Before building a job-profile report, inspect Job Catalog and other delivered options.","Workday Standard Reports;Copy Standard Report to Custom Report;Business Process Configuration Options;Reorganizations;Job Catalog;Hide Workday Delivered Report","Report availability and row-level data both depend on security.","What controls report access and visible data?|Security to the report and underlying data.","First step before creating a custom report?|Check standard reports|Change the staffing model|Create a security group|Edit a business process",0,"A delivered report may already meet the requirement.","report,b1,b2","B1 pp. 39–42, 48, 69, 71, 157, 268 · B2 pp. 175–176, 181, 243"],
["custom-reports","reporting","Create Custom Reports","Choose a data source and objects before configuring fields, filters, prompts, sorting, and sharing.","The data source is the most important choice: it sets the population and the primary business object, and it is the biggest factor in report performance. Advanced reports reach related objects one level deep; deeper data needs a calculated field. Advanced report tabs: Columns (fields), Sort, Filter (primary object), Subfilter (related objects; runs before the filter), Prompts (defaults and hiding), Output (table, chart, worklet), Share, and Advanced (web service, temporary report date, Optimized for Performance). Test returns the first 10 rows; Run returns all.","Data source|Defines population;Primary object|Anchors related objects;Filter vs subfilter|Primary object vs related objects (subfilter runs first);Share|Only to users with access to the data source and filter","For worker, manager, and cost-center data, choose a source whose primary object exposes those relationships.","Create Custom Report;Copy Standard Report to Custom Report;Business Object Details;Schedule a Report;Scheduled Future Processes;Create Custom Report from Here","Do not begin with columns. Confirm the population and object relationships first.","What determines available primary objects?|The report data source.","A needed field is unavailable. Inspect first?|Data source and object relationships|Notification trigger settings|Staffing model restrictions|Role assignment inheritance",0,"Object relationships govern available fields.","report,custom,b1,b2","B1 pp. 38–50 · B2 pp. 174–237, 264"],
["navigation","reporting","Navigation, Search & Tenants","Find tasks, objects, and events quickly, and know your tenant types.","A tenant is one instance of Workday. Workday metadata cannot change; your configuration and data are tenanted data. Feature releases come twice a year, and service updates arrive weekly. Search shows predictive results after three characters and treats each term separately; Exact Match finds IDs and email addresses. The Workday Touchpoints Kit shows data flows and configuration relationships across products.","Production vs Sandbox|Live data vs a test copy;bp: vs event:|Definitions vs running events;Related Actions|What you can do with an object;Proxy|Testing as another user, never in Production","You need the Hire definition for IT HelpDesk. Search bp: hire help, then use the definition's Related Actions to edit it.","Start Proxy;Stop Proxy;Edit Tenant Setup - Search;Workday Standard Reports;Find Events","Proxy access policies apply to non-production tenants only, and only unconstrained security groups can be given proxy access.","Which search prefix finds business process definitions?|bp:","Which tool shows data flows and configuration relationships across Workday products?|Workday Touchpoints Kit|Functional Areas report|Workday Community|Business process security policies",0,"The Touchpoints Kit visually displays data flows and configuration relationships (B1 p. 20).","nav,b1","B1 pp. 16–40, 52"],
["security-framework","security","Configurable Security Framework","Trace access from user to group to policy to secured item.","Users become members of security groups. Domains group securable tasks, reports, data sources, fields, and integrations.","Domain policy|View or modify secured items;BP policy|Initiate or act on events","When a user cannot run a report, trace its securing domain, permitted groups, and the user’s membership.","View Security for Securable Item;Security Analysis for Securable Item and Account;Domain Security Policies for Functional Area","Creating a group or assigning a role does not grant access until a relevant policy gives permission.","What two things align for access?|Group membership and policy permission.","A group member cannot run a report. Inspect?|Report domain policy|Organization staffing model|Job family assignment|Process completion step",0,"Membership needs matching policy permission.","security,b1,b2","B1 pp. 55, 208–216, 242–244 · B2 p. 144"],
["security-groups","security","Security Group Types","Choose the right membership method and constraint context.","Groups get members three ways: Workday-assigned (Workday defines and maintains members, such as Employee As Self and All Employees), manually assigned (administrators assign users, as in user-based groups), and derived (membership follows criteria such as role assignments, as in role-based groups). Role-based groups can be constrained or unconstrained. The context type describes what target data members can reach: unconstrained (no organizational limit), constrained to their own instance (self-service groups), constrained to public data, or constrained to the organizations where the member holds the role or belongs.","Role-based constrained|Role membership plus supported context;User-based|Named maintained membership;Workday-delivered|Workday-owned criteria;Membership methods|Workday-assigned, manually assigned, derived;Context type|What target data members can reach","Use role-based constrained security for regional HR partners who should see only workers in organizations they support.","Create Security Group;Assign Roles;Assign Users to User-Based Security Group","Wrong constraint context can create broad access even when membership is correct.","What drives role-based group membership?|Assignable-role assignment.","Regional partners need supported-org access. Best type?|Role-based constrained|User-based unconstrained|Workday-delivered All Users|Job-based unconstrained",0,"Role-based constrained groups follow roles and target context.","security,groups,roles,b1,b2","B1 pp. 215–233, 250 · B2 pp. 144–145"],
["security-advanced","security","Advanced Security Group Types","Pick the right job, membership, combination, rule-based, or non-worker group.","Some groups derive members from worker data. Job-based groups use one job criterion, such as job profile, job family, or management level, and can be constrained to the member's own organizations or unconstrained. Location membership groups include workers at chosen locations and are always unconstrained. Organization membership groups include members of chosen organizations, including hierarchies, and can be constrained or unconstrained. Combination groups reuse other groups. Aggregation: members of any included group, each keeping its own constraints. Intersection: members of all included groups, with constraints intersected; it cannot include intersection, rule-based, or integration system groups.","Aggregation|Any included group (union);Intersection|All included groups, constraints intersected;Rule-based|Baseline group filtered by a security rule;Integration system|Access for integration system users (ISUs)","Only employees in Australia should update their own legal name. Create a rule-based group with Employee As Self as the baseline and a rule on country, then use it in the self-service policy.","Create Security Group;Create Security Rule;Test Security Rule;View Security Groups for User;Maintain Fields for Security Rules","Location membership groups are always unconstrained. To limit what members see by location, use an organization membership (constrained) group on a location hierarchy.","Which group type combines groups so members of any of them qualify?|Aggregation.","Only employees based in Australia should update their legal name. Which group type limits that self-service access?|Rule-based|Aggregation|Job-based|Location membership",0,"A rule-based group filters a baseline group such as Employee As Self with a security rule (B2 pp. 161–163).","groups,secadv,b2","B2 pp. 143–166, 256–263, 274–275"],
["security-policies","security","Domain vs BP Security Policies","Separate secured-item access from business-process participation, then activate changes.","Domain policies grant View or Modify (and Get or Put for integrations) to items in a domain; Modify includes View, Put includes Get, and child domains inherit from their parent.","Can see or modify an item?|Domain policy;Can initiate or approve an event?|BP policy;Template-driven process|Needs both BP and domain permissions","If HR can view worker data but cannot initiate Change Job, inspect Change Job BP security rather than adding broad domain access.","Edit Domain Security Policy;Business Process Policy > Edit;Activate Pending Security Policy Changes;View Security for Securable Item","Saving a policy edit does not activate it. Review, activate, and test with suitable accounts.","What activates saved policy edits?|Activate Pending Security Policy Changes.","Can view data but cannot initiate Change Job. Inspect?|Change Job BP policy|Worker-data View only|Job family|Organization hierarchy",0,"Event initiation is governed by the BP policy.","security,policy,b1,b2","B1 pp. 213, 236–242, 250 · B2 pp. 93–98"]];
const G=[["Aggregation security group","Members in any included group, each keeping its own constraints."],["Assignable role","Responsibility for an organization or role-enabled instance used by role-based security."],["Business object","A record type with fields and relationships, such as Worker."],["Business process definition","Configured steps, routing, conditions, notifications, and completion behavior."],["Business process event","One transaction based on a definition."],["Compensation grade profile","A localized pay range within a grade, such as by country."],["Compensation package","A group of compensation grades and plans used to default pay."],["Completion step","The point when event data commits and status becomes Successfully Completed."],["Condition rule","Logic affecting whether workflow starts, continues, routes, or completes."],["Domain","A collection of securable items sharing a policy."],["Domain security policy","Controls group access to items in a domain."],["Hiring restrictions","Permitted job, location, worker, subtype, or time criteria for staffing."],["Intersection security group","Members in all included groups, with their constraints intersected."],["Job family","Optional grouping of related job profiles."],["Job Management","Flexible staffing with restrictions at supervisory-organization level."],["Job overlap","Two workers holding the same position for a limited time, used to train or cover."],["Job profile","Reusable definition of work characteristics."],["Organization hierarchy","Parent-child organization rollup."],["Position Management","Staffing model with persistent individual positions."],["Reorganization event","Groups organization changes under one common effective date."],["Report data source","Defines a report population and available primary objects."],["Routing restriction","Excludes the initiator, prior approvers, or event subject from a step, with an optional alternate group."],["Rule-based definition","A business process definition chosen at initiation when its single condition rule is met."],["Security group","Collection of users granted access through policies."],["Staffing model","Determines how a supervisory organization defines and fills work."],["Supervisory organization","Foundational HCM management hierarchy."]];
const KEY='hcm-core-lab-v3';let st=(()=>{try{let v=JSON.parse(localStorage.getItem(KEY)||'null');return v&&typeof v==='object'?v:null}catch(e){return null}})()||{lessons:{},cards:{}};st.lessons=st.lessons||{};st.cards=st.cards||{};let deck=[],quiz=null,tick=null;const $=x=>document.querySelector(x),$$=x=>[...document.querySelectorAll(x)];const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(st))}catch(e){}};const dm=id=>D.find(x=>x[0]===id);const ls=id=>st.lessons[id]||{opened:false,done:false,confidence:0};/* Readiness: the share of each domain's practice questions whose latest answer was right, weighted by the exam blueprint. Questions not yet answered count as not right. */
const qpct=d=>{let qs=allQ().filter(q=>q.d===d),h=hist();return qs.length?Math.round(qs.filter(q=>h[q.q]&&!h[q.q].w).length/qs.length*100):0};
const ready=()=>Math.round(D.reduce((a,d)=>a+qpct(d[0])*d[2]/100,0));
const PAGES=['home','plan','learn','cards','practice','glossary'];
function go(hash){if(location.hash!=='#'+hash)history.pushState(null,'','#'+hash)}
function navActive(p){$$('nav a').forEach(x=>{let on=x.dataset.page===p;x.classList.toggle('active',on);if(on)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')})}
function page(id,push=true){if(push&&id!=='lesson')go(id);$$('.page').forEach(x=>x.classList.toggle('active',x.id===id));navActive(id==='lesson'?'learn':id);if(id==='home')home();if(id==='plan'&&typeof renderPlan==='function')renderPlan();if(id==='learn')learn();if(id==='cards')cards();if(id==='practice')practice();if(id==='glossary')glossary();scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(push&&id!=='lesson')focusTitle('#'+id)}
/* After navigating, move focus to the new page's title so keyboard and screen-reader users start there. */
function focusTitle(sel){let h=$(sel+' h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}
function route(){let [h,qs]=location.hash.slice(1).split('?'),m=h.match(/^lesson\/([^/]+)(\/quiz)?$/);if(m&&L.some(x=>x[0]===m[1])){if(m[2])startLessonQuiz(m[1],false);else openLesson(m[1],false)}else{if(h&&!PAGES.includes(h))history.replaceState(null,'','#home');if(h==='learn'){let p=new URLSearchParams(qs||'');fillDomains();$('#domainFilter').value=p.get('domain')||'all';$('#progressFilter').value=p.get('progress')||'all';if(!$('#domainFilter').value)$('#domainFilter').value='all';if(!$('#progressFilter').value)$('#progressFilter').value='all'}page(PAGES.includes(h)?h:'home',false)}}
addEventListener('popstate',()=>{$$('dialog[open]').forEach(d=>d.close());route()});
function home(){let p=ready();$('#ready').textContent=p+'%';$('#ring').setAttribute('aria-valuenow',p);$('#ring').setAttribute('aria-valuetext',p+'% ready');$('#ring').style.setProperty('--value',p*3.6+'deg');let done=L.filter(x=>ls(x[0]).done).length;let weak=D.reduce((m,d)=>qpct(d[0])<qpct(m[0])?d:m);$('#readyLabel').textContent=p?`Weakest domain: ${weak[1]} (${qpct(weak[0])}%)`:'Answer practice questions to start';$('#readyCopy').textContent=`Latest answers on ${allQ().length} practice questions, weighted by exam domain · ${done} of ${L.length} lessons complete`;$('#domains').innerHTML=D.map(d=>`<button class="domain-card" data-domain="${d[0]}" aria-label="${d[1]}: ${qpct(d[0])}% right, ${d[2]}% of exam"><div><span>${d[2]}% of exam</span><b>${qpct(d[0])}%</b></div><span class="dc-name">${d[1]}</span><div class="track"><i style="width:${qpct(d[0])}%"></i></div></button>`).join('');$('#heroCopy').textContent=`${L.length} lessons covering the 19 objectives in the official exam guide, grouped by exam domain.`;$$('[data-domain]').forEach(b=>b.onclick=()=>{page('learn');$('#domainFilter').value=b.dataset.domain;learn()})}
function fillDomains(){if($('#domainFilter').options.length===1)D.forEach(d=>$('#domainFilter').add(new Option(`${d[1]} · ${d[2]}%`,d[0])))}
function learn(){$('#learnTitle').textContent=`${L.length} lessons`;fillDomains();let df=$('#domainFilter').value,pf=$('#progressFilter').value,q=new URLSearchParams();if(df!=='all')q.set('domain',df);if(pf!=='all')q.set('progress',pf);let want='#learn'+(q.toString()?'?'+q:'');if(/^#learn(\?|$)/.test(location.hash)&&location.hash!==want)history.replaceState(null,'',want);let done=L.filter(x=>ls(x[0]).done).length;$('#coverage').innerHTML=`<b>${done}/${L.length} completed.</b> Every objective in the exam guide is covered, checked against the HCM Core course books (Oct 2026).`;let list=L.filter(x=>df==='all'||x[1]===df).filter(x=>pf==='all'||pf==='done'&&ls(x[0]).done||pf==='started'&&ls(x[0]).opened&&!ls(x[0]).done||pf==='new'&&!ls(x[0]).opened);$('#lessonList').innerHTML=D.filter(d=>df==='all'||d[0]===df).map(d=>{let z=list.filter(x=>x[1]===d[0]);return z.length?`<section class="domain-section"><h2>${d[1]} <small>${d[2]}% of exam</small></h2>${z.map(x=>{let q=ls(x[0]),c=q.done?'done':q.opened?'started':'';return`<button class="objective" data-lesson="${x[0]}"><span class="num">${String(L.indexOf(x)+1).padStart(2,'0')}</span><span><b>${x[2]}</b><small>${x[3]}</small></span><span class="badge ${c}">${q.done?'Complete':q.opened?'In progress':'Not started'}</span></button>`}).join('')}</section>`:''}).join('')||'<p class="empty">No objectives match these filters.</p>';$$('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson))}
function tldrHTML(id,t=typeof TLDR!=='undefined'&&TLDR[id]){if(!t)return'';return`<article class="tldr"><h2>TL;DR: key exam facts</h2><ul>${t.map(v=>{let i=v.indexOf('|');return`<li>${i>0?`<b>${v.slice(0,i)}:</b> ${v.slice(i+1)}`:v}</li>`}).join('')}</ul></article>`}
function notesHTML(id){let n=typeof N!=='undefined'&&N[id];if(!n)return'';return`<details class="lesson-card fold"><summary><h2>Study notes</h2><span>${n.length} topics from the course books</span></summary><div class="notes">${n.map(([h,cite,items])=>`<article class="note"><h3>${h}</h3><ul>${items.map(t=>{let i=t.indexOf('|');return`<li>${i>0?`<b>${t.slice(0,i)}</b> ${t.slice(i+1)}`:t}</li>`}).join('')}</ul><p class="book-cite">Course book: ${cite}</p></article>`).join('')}</div></details>`}
function sourcesHTML(x){let link=k=>`<a href="${S[k][1]}" target="_blank" rel="noopener">${S[k][0]}<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`,keys=x[13].split(','),web=keys.filter(k=>!/^b[12]$/.test(k)),books=keys.filter(k=>/^b[12]$/.test(k));return`<details class="lesson-card fold"><summary><h2>Sources</h2><span>Workday pages and course-book pages</span></summary>${web.length?`<h3 class="src-h">Official Workday pages</h3><div class="source-links">${web.map(link).join('')}</div>`:''}<h3 class="src-h">Course books</h3><div class="source-links">${books.map(link).join('')}</div>${x[14]?`<p class="book-cite"><b>Pages:</b> ${x[14]}</p>`:''}</details>`}
function guideHTML(id){let g=typeof EG!=='undefined'&&EG[id];if(!g)return'';let sup=g.supports?`<p class="eg-sup">${g.supports==='overview'?'Supports the exam guide\u2019s overview section.':'Supports this exam guide topic (main lesson: '+L.find(y=>y[0]===g.supports)[2]+').'}</p>`:'';return`<section class="lesson-card exam-guide"><h2>Exam guide check</h2><p class="eg-topic">${g.topic}</p><p class="eg-meta">${g.domain}${g.weight?` · ${g.weight}% of the exam`:''} · <a href="${GUIDE_URL}" target="_blank" rel="noopener">Open the exam guide<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a></p>${sup}<p class="eg-note">Answer each requirement from memory, then tap it to check. Requirements are restated from the guide; open it for the exact wording. Answers come from the course books.</p><ol class="eg-list">${g.reqs.map(([r,a,c,v])=>`<li><details class="eg-item"><summary class="eg-req">${r}<span class="eg-show" aria-hidden="true"><span class="eg-closed">Show answer</span><span class="eg-opened">Hide answer</span></span></summary><div class="eg-ans"><p>${a}</p><p class="book-cite">Course book: ${c}</p>${v?`<button class="eg-vis" data-vis="${v.replace(/"/g,'&quot;')}"><i class="ph ph-chart-bar" aria-hidden="true"></i> See diagram: ${v}</button>`:''}</div></details></li>`).join('')}</ol></section>`}
