function afterComplete(id){if(typeof lessonDays!=='function')return'';let days=lessonDays(id).filter(([wi,si])=>st.plan[`${wi}-${si}`]).map(([wi,si])=>`Week ${wi+1} · Day ${si+1}`),n=nextSession(),s=n&&WEEKS[n[0]].sessions[n[1]];return`${days.length?`<p class="complete-note">${days.join(', ')} marked complete in your plan.</p>`:''}${s?`<button id="nextSession" class="primary complete" data-w="${n[0]}" data-d="${n[1]}">Next: ${s[1]}<i class="ph ph-arrow-right" aria-hidden="true"></i></button>`:''}`}
