const TOC={'The mental model':'Model','Know the distinction':'Distinction','Apply it':'Apply','Tasks and reports to recognize':'Tasks','Exam trap':'Trap','TL;DR: key exam facts':'TL;DR','Study notes':'Notes','Sources':'Sources','Exam guide check':'Exam guide','Lesson quiz':'Quiz'};let tocObs;
function lessonToc(){let secs=[],vis=false;[...$('#lesson').children].forEach((el,i)=>{let h=el.querySelector('h2');if(!h||el.classList.contains('lesson-head'))return;let label=TOC[h.textContent.trim()];if(!label&&el.querySelector('.vis')&&!vis){label='Diagrams';vis=true}if(!label)return;el.id='sec-'+i;secs.push([el.id,label])});$('#lesson .lesson-head').insertAdjacentHTML('afterend',`<div role="navigation" class="lesson-toc" aria-label="Lesson sections">${secs.map(([id,l])=>`<button data-sec="${id}">${l}</button>`).join('')}</div>`);let toc=$('.lesson-toc'),mark=id=>{toc.querySelectorAll('button').forEach(b=>{let on=b.dataset.sec===id;b.classList.toggle('active',on);if(on){b.setAttribute('aria-current','true');if(toc.scrollWidth>toc.clientWidth)toc.scrollLeft=b.offsetLeft-16}else b.removeAttribute('aria-current')})};toc.querySelectorAll('button').forEach(b=>b.onclick=()=>{let el=document.getElementById(b.dataset.sec),h=el.querySelector('h2');el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});h.tabIndex=-1;h.focus({preventScroll:true});mark(b.dataset.sec)});if(tocObs)tocObs.disconnect();tocObs=new IntersectionObserver(es=>{let v=es.filter(e=>e.isIntersecting);if(v.length)mark(v[0].target.id)},{rootMargin:'-140px 0px -65% 0px'});secs.forEach(([id])=>tocObs.observe(document.getElementById(id)))}
function openLesson(id,push=true){if(push)go('lesson/'+id);let x=L.find(y=>y[0]===id),q=ls(id);st.lessons[id]={...q,opened:true};save();let decisions=x[5].split(';').map(v=>v.split('|'));$('#lesson').innerHTML=`<header class="lesson-head"><div class="lesson-nav"><button id="back"><i class="ph ph-arrow-left" aria-hidden="true"></i>All lessons</button></div><p class="kicker">${dm(x[1])[1]} · Lesson ${L.indexOf(x)+1} of ${L.length}</p><h1>${x[2]}</h1><p>${x[3]}</p></header><article class="lesson-card"><h2>The mental model</h2><p>${x[4]}</p></article>${typeof VIS!=='undefined'&&VIS[x[0]]?VIS[x[0]]():''}<article class="lesson-card"><h2>Know the distinction</h2><div class="decision-grid">${decisions.map(v=>`<div class="decision"><b>${v[0]}</b><span>${v[1]}</span></div>`).join('')}</div></article><article class="lesson-card"><h2>Apply it</h2><p>${x[6]}</p></article><article class="lesson-card"><h2>Tasks and reports to recognize</h2><ul>${x[7].split(';').map(v=>`<li>${v}</li>`).join('')}</ul><p><small>Exact availability and paths vary by tenant configuration and security.</small></p></article><article class="trap"><h2><i class="ph ph-warning" aria-hidden="true"></i>Exam trap</h2><p>${x[8]}</p></article>${tldrHTML(x[0])}${notesHTML(x[0])}${sourcesHTML(x)}${guideHTML(x[0])}<article class="lesson-card" id="quizCard"><h2 tabindex="-1">Lesson quiz</h2><p>5 questions per quiz from a bank of ${lessonQs(id).length}. ${(n=>n?`${n} you have not seen yet. Each retake uses new questions first.`:'You have seen them all; retakes start with ones you missed.')(lessonQs(id).filter(q=>!hist()[q.q]).length)}</p><button id="lessonQuiz" class="primary">Start lesson quiz</button></article><article class="lesson-card"><h2>How confident are you?</h2><div class="confidence">${['Learning','Almost','Confident'].map((v,i)=>`<button data-confidence="${i+1}" class="${q.confidence===i+1?'selected':''}" aria-pressed="${q.confidence===i+1}">${v}</button>`).join('')}</div>${q.done?'<button id="complete" class="secondary complete is-done"><i class="ph ph-check" aria-hidden="true"></i>Completed</button>'+afterComplete(id):(q.best||0)>=80?`<p class="complete-note">Best quiz score: ${q.best}%</p><button id="complete" class="secondary complete">Mark objective complete</button>`:`<p class="complete-note" id="completeNote">${q.best?`Best quiz score: ${q.best}%. `:''}Pass the lesson quiz with 80% or higher to mark this objective complete.</p><button id="complete" class="secondary complete" disabled aria-describedby="completeNote">Mark objective complete</button>`}</article>`;page('lesson',false);if(push)focusTitle('#lesson');$$('.eg-vis').forEach(b=>b.onclick=()=>{let h=$$('#lesson .vis').map(v=>v.closest('article')).find(a=>a&&a.querySelector('h2')?.textContent===b.dataset.vis);if(h){h.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});h.classList.add('eg-flash');setTimeout(()=>h.classList.remove('eg-flash'),1600)}});lessonToc();$('#back').onclick=()=>page('learn');$('#lessonQuiz').onclick=()=>startLessonQuiz(id);$$('[data-confidence]').forEach(b=>b.onclick=()=>{st.lessons[id]={...ls(id),confidence:+b.dataset.confidence};save();$$('[data-confidence]').forEach(v=>{v.classList.toggle('selected',v===b);v.setAttribute('aria-pressed',v===b)})});$('#complete').onclick=()=>{let done=!ls(id).done;st.lessons[id]={...ls(id),done,opened:true};if(typeof lessonDays==='function')lessonDays(id).forEach(([wi,si])=>st.plan[`${wi}-${si}`]=done);save();openLesson(id,false);$('#complete').focus()};let ns=$('#nextSession');if(ns)ns.onclick=()=>startDay(+ns.dataset.w,+ns.dataset.d)}
function buildDeck(){deck=L.flatMap(x=>[x[9].split('|'),...(typeof C!=='undefined'&&C[x[0]]||[])].map(([f,b],i)=>({id:i?x[0]+'#'+i:x[0],d:x[1],f,b})))}
function cards(){buildDeck();cardStats();showCard()}
function dueCards(){let now=Date.now(),next=x=>st.cards[x.id]?.next||0;return deck.filter(x=>next(x)<=now).sort((a,b)=>next(a)-next(b))}
function cardStats(){$('#due').textContent=dueCards().length;$('#mastered').textContent=Object.values(st.cards).filter(x=>x.days>=7).length}
function showCard(){let q=dueCards(),x=q[0],fc=$('#flashcard');$('#ratings').hidden=true;fc.classList.remove('revealed');fc.disabled=!x;if(!x){let n=new Date(Math.min(...deck.map(c=>st.cards[c.id]?.next||0)));$('#cardMeta').textContent='All caught up';$('#cardFront').textContent='No cards are due right now.';$('#cardBack').textContent=`Next card is due ${n.toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'})}.`;fc.classList.add('revealed');return}$('#cardMeta').textContent=`${dm(x.d)[1]} · ${q.length} due`;$('#cardFront').textContent=x.f;$('#cardBack').textContent=x.b}
function shuf(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function shuffleQ(q){let idx=shuf(q.o.map((_,i)=>i));return{...q,o:idx.map(i=>q.o[i]),a:idx.indexOf(q.a)}}
function question(x){let p=x[10].split('|');return{d:x[1],l:x[0],q:p[0],o:p.slice(1),a:x[11],e:x[12]}}
function lessonQs(id){let x=L.find(y=>y[0]===id);return[question(x),...(QB[id]||[]).map(r=>({d:x[1],l:id,q:r[0],o:r.slice(1,5),a:0,e:r[5]}))]}
function allQ(){return L.flatMap(x=>lessonQs(x[0]))}
function hist(){return st.qs||(st.qs={})}
function pick(pool,n){let h=hist(),seen=q=>h[q.q],un=shuf(pool.filter(q=>!seen(q))),miss=shuf(pool.filter(q=>seen(q)&&h[q.q].w)),rest=shuf(pool.filter(q=>seen(q)&&!h[q.q].w)).sort((a,b)=>h[a.q].n-h[b.q].n);return[...un,...miss,...rest].slice(0,n)}
function lessonQuiz(id){return pick(lessonQs(id),5)}
function domainQ(d,n=15){return pick(allQ().filter(x=>x.d===d),n)}
function examQ(){let targets={staffing:13,organizations:10,business:12,reporting:3,security:12},out=[];Object.entries(targets).forEach(([d,n])=>out.push(...domainQ(d,n)));return out}
function practice(){if(quiz&&!quiz.done){$('#practiceMenu').hidden=true;$('#quiz').hidden=false;return}clearInterval(tick);$('#practiceMenu').hidden=false;$('#quiz').hidden=true;$('#practiceDomains').innerHTML=D.map(d=>`<button class="practice-domain" data-practice="${d[0]}"><span><b>${d[1]}</b><small>15 random questions from ${allQ().filter(x=>x.d===d[0]).length} · ${d[2]}% of exam</small></span><i class="ph ph-caret-right" aria-hidden="true"></i></button>`).join('');$$('[data-practice]').forEach(b=>b.onclick=()=>startQuiz(domainQ(b.dataset.practice),false))}
function startQuiz(qs,exam,lesson=null,redo=null){if(quiz&&quiz.exam&&!quiz.done&&!confirm('You have a mock exam in progress. Leave it and start this quiz? Your exam answers will not be saved.')){page('practice');return}clearInterval(tick);let h=hist();quiz={qs:shuf(qs).map(shuffleQ),ans:[],fresh:qs.filter(q=>!h[q.q]).length,i:0,score:0,exam,lesson,redo,end:exam?Date.now()+7200000:0};$('#practiceMenu').hidden=true;$('#quiz').hidden=false;if(exam)tick=setInterval(timer,1000);showQ()}
function timer(){if(!quiz?.exam)return;let left=Math.max(0,quiz.end-Date.now()),e=$('#timer');if(e)e.textContent=`${Math.floor(left/60000)}:${String(Math.floor(left%60000/1000)).padStart(2,'0')}`;if(!left)finish()}
function showQ(){let q=quiz.qs[quiz.i];if(!q)return finish();$('#quiz').innerHTML=`<div class="quiz-top"><button id="exit">Exit</button><span>${quiz.i+1} / ${quiz.qs.length}</span><span id="timer">${quiz.exam?'120:00':'Score '+quiz.score}</span></div>${quiz.i===0&&quiz.fresh<quiz.qs.length?`<p class="quiz-note">${quiz.fresh?`${quiz.fresh} new question${quiz.fresh>1?'s':''} left in this set. The rest are repeats, starting with ones you missed.`:'You have seen every question in this set. Repeats start with ones you missed.'}</p>`:''}<article class="question"><p class="kicker">${dm(q.d)[1]} · ${L.find(y=>y[0]===q.l)[2]}</p><h2>${q.q}</h2><div class="options">${q.o.map((v,i)=>`<button data-qa="${i}">${v}</button>`).join('')}</div><div class="feedback" hidden></div><button class="primary quiz-next" hidden>Next question</button></article>`;$('#exit').onclick=()=>{if(quiz.exam&&!confirm('Leave the mock exam? Your answers so far will not be saved.'))return;quiz.done=true;clearInterval(tick);practice()};$$('[data-qa]').forEach(b=>b.onclick=()=>{let a=+b.dataset.qa,ok=a===q.a,h=hist();if(ok)quiz.score++;quiz.ans[quiz.i]=a;h[q.q]={n:(h[q.q]?.n||0)+1,w:!ok};save();$$('[data-qa]').forEach((v,i)=>{v.disabled=true;if(i===q.a)v.classList.add('correct');else if(i===a)v.classList.add('wrong')});let f=$('.question .feedback');f.hidden=false;f.className='feedback '+(ok?'is-ok':'is-bad');f.innerHTML=explain(q,a);$('#srStatus').textContent=f.innerText;let n=$('.quiz-next');n.hidden=false;n.focus();n.onclick=()=>{quiz.i++;showQ()}});timer()}
function explain(q,a){let ok=a===q.a;return`<b>${ok?'Correct':'Incorrect'}</b>${ok?'':`<p>You chose: ${a==null?'No answer':q.o[a]}</p><p>Correct answer: ${q.o[q.a]}</p>`}<p><span>Why:</span> ${q.e}</p>`}
function review(){let{qs,ans}=quiz,miss=qs.filter((q,i)=>ans[i]!==q.a).length;return`<section class="quiz-review"><div class="review-head"><h2>Review your answers</h2>${miss&&miss<qs.length?'<label><input type="checkbox" id="onlyMissed"> Only missed</label>':''}</div><ol>${qs.map((q,i)=>{let a=ans[i],ok=a===q.a;return`<li class="review-item ${ok?'is-ok':'is-bad'}"><p class="kicker">${ok?'Right':'Missed'} · ${L.find(y=>y[0]===q.l)[2]}</p><h3>${q.q}</h3><div class="feedback ${ok?'is-ok':'is-bad'}">${explain(q,a)}</div></li>`}).join('')}</ol></section>`}
function finish(){clearInterval(tick);quiz.done=true;let p=Math.round(quiz.score/quiz.qs.length*100);if(quiz.lesson){let l=ls(quiz.lesson);st.lessons[quiz.lesson]={...l,best:Math.max(l.best||0,p)};save()}$('#quiz').innerHTML=`<article class="score"><strong>${p}%</strong><h2>${p>=80?'80% or higher':'Below 80%'}</h2><p>${quiz.score} of ${quiz.qs.length} correct</p><div class="score-actions"><button id="retake" class="primary">Retake with new questions</button><button id="again" class="secondary">${quiz.lesson?'Back to lesson':'Return to practice'}</button></div></article>${review()}`;let ob=$('#onlyMissed');if(ob)ob.onchange=()=>$('.quiz-review').classList.toggle('only-missed',ob.checked);let {lesson,exam,qs,redo}=quiz;$('#retake').onclick=()=>startQuiz(redo?redo():lesson?lessonQuiz(lesson):exam?examQ():domainQ(qs[0].d,qs.length),exam,lesson,redo);$('#again').onclick=lesson?()=>openLesson(lesson):practice}
function glossary(q=''){q=q.toLowerCase();$('#terms').innerHTML=G.filter(x=>x.join(' ').toLowerCase().includes(q)).map(x=>`<article class="term"><b>${x[0]}</b><p>${x[1]}</p></article>`).join('')||'<p class="empty">No terms match that search.</p>'}
function search(q){q=q.toLowerCase().trim();let z=q?L.filter(x=>[x.join(' '),typeof N!=='undefined'&&N[x[0]]?N[x[0]].flat(2).join(' '):'',typeof TLDR!=='undefined'&&TLDR[x[0]]?TLDR[x[0]].join(' '):''].join(' ').toLowerCase().includes(q)):[];$('#results').innerHTML=q?(z.map(x=>`<button class="result" data-result="${x[0]}"><b>${x[2]}</b><small>${dm(x[1])[1]} · ${x[3]}</small></button>`).join('')||'<p class="empty">No lessons match that search.</p>'):'<p class="empty">Search lessons, task names, and concepts.</p>';$$('[data-result]').forEach(b=>b.onclick=()=>{$('#searchDialog').close();openLesson(b.dataset.result)})}
$$('[data-page]').forEach(b=>b.onclick=e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button)return;e.preventDefault();page(b.dataset.page)});$('#domainFilter').onchange=learn;$('#progressFilter').onchange=learn;$('#flashcard').onclick=()=>{$('#flashcard').classList.add('revealed');$('#ratings').hidden=false};$$('[data-rate]').forEach(b=>b.onclick=()=>{let x=dueCards()[0];if(!x)return;let old=st.cards[x.id]?.days||0,days=b.dataset.rate==='again'?0:b.dataset.rate==='hard'?Math.max(1,old):Math.max(3,old*2||3);st.cards[x.id]={days,next:Date.now()+days*86400000};save();cardStats();showCard()});$('#examBtn').onclick=$('#examHome').onclick=()=>{page('practice');startQuiz(examQ(),true)};$('#termSearch').oninput=e=>glossary(e.target.value);$('#searchBtn').onclick=()=>{$('#searchDialog').showModal();$('#globalSearch').focus();search('')};$('#globalSearch').oninput=e=>search(e.target.value);$('#sourcesBtn').onclick=()=>{$('#sourceList').innerHTML=Object.values(S).map(x=>`<article class="source-item"><a href="${x[1]}" target="_blank" rel="noopener">${x[0]}<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a><p>Reference used for the lessons.</p></article>`).join('');$('#sourceDialog').showModal()};home();route();
